const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {spawnSync} = require('node:child_process');
const test = require('node:test');
const root = path.resolve(__dirname, '..');
const read = name => fs.readFileSync(path.join(root, name), 'utf8');

// AI: below section was generated by an AI
const between = (source, start, end) => {
  const a = source.indexOf(start), b = source.indexOf(end, a);
  assert.ok(a >= 0 && b > a, `missing production block: ${start}`);
  return source.slice(a, b);
};

test('actual setup AP policy and browser routing remain local-only in Compatibility and captive in stock', async t => {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'castletek-setup-ap-'));
  try {
    const main = read('wled00/wled.cpp'), server = read('wled00/wled_server.cpp');
    const helper = read('wled00/castletek_wled_setup.cpp')
      .replace('#include "wled.h"', '').replace('#include <esp_netif.h>', '');
    const unavailable = between(server, 'static bool castleTekWLEDIsUnavailableSettingsPage(', '\n// Chromium');
    const fallback = between(server, '  server.onNotFound([](AsyncWebServerRequest *request){', '\n}\n\n\nvoid serveMessage(');
    const source = read('test/fixtures/castletek-setup-ap-host.h') + '\n' +
      between(read('wled00/util.cpp'), 'void checkSettingsPIN(', '\n\nuint16_t crc16') + '\n' +
      helper + '\n' +
      between(main, 'void WLED::initAP(bool resetAP)', '\nvoid WLED::initConnection()') + '\n' +
      '#ifdef CASTLETEK_WLED_COMPAT\n' + unavailable + '\n#endif\n' +
      between(server, 'static bool captivePortal(', '\nvoid initServer()') + '\n' +
      'static void hostRegisterFallback() {\n' + fallback + '\n}\n' +
      server.slice(server.indexOf('void serveSettings(AsyncWebServerRequest* request, bool post) {')) + '\n' +
      read('test/fixtures/castletek-setup-ap-host.cpp');
    const sourcePath = path.join(temporary, 'setup-ap.cpp');
    fs.writeFileSync(sourcePath, source);
    for (const mode of ['compat', 'stock']) {
      const binary = path.join(temporary, mode);
      const args = ['-std=c++17', '-Wall', '-Wextra', '-Werror', '-Wno-unused-function', '-Wno-unused-variable', '-Wno-unused-parameter',
        '-DARDUINO_ARCH_ESP32', '-DWLED_DISABLE_OTA', '-DWLED_DISABLE_2D', '-DWLED_DISABLE_ALEXA',
        '-I', path.join(root, 'wled00')];
      if (mode === 'compat') args.push('-DCASTLETEK_WLED_COMPAT');
      const compiled = spawnSync(process.env.CXX || 'c++', [...args, sourcePath, '-o', binary], {encoding:'utf8', timeout:60000});
      assert.equal(compiled.status, 0, compiled.stderr || String(compiled.error));
      for (const scenario of ['startup', 'channel', 'failures', 'repeat', 'ports', 'captive', 'browser']) {
        await t.test(`${mode}/${scenario}`, () => {
          const ran = spawnSync(binary, [scenario], {encoding:'utf8', timeout:10000});
          assert.equal(ran.status, 0, ran.stderr || String(ran.error));
          assert.match(ran.stdout, /Setup AP checks passed: \d+/);
          process.stdout.write(ran.stdout);
        });
      }
    }
  } finally {
    fs.rmSync(temporary, {recursive:true, force:true});
  }
});

test('Compatibility excludes every wildcard DNS object and lifecycle call while keeping explicit settings registration', () => {
  // The compiled Compatibility fixture deliberately has no DNS server symbol.
  // Also check lifecycle paths outside initAP, including JSON-triggered reset.
  const source = read('wled00/wled.cpp') + '\n' + read('wled00/wled.h') + '\n' + read('wled00/json.cpp');
  const active = [];
  let depth = 0;
  for (const line of source.split('\n')) {
    if (/^\s*#ifndef CASTLETEK_WLED_COMPAT\s*$/.test(line)) active.push(depth);
    if (/^\s*#\s*(if|ifdef|ifndef)\b/.test(line)) depth++;
    if (/\bdnsServer\b/.test(line)) assert.ok(active.length > 0, `unguarded DNS reference: ${line.trim()}`);
    if (/^\s*#\s*endif\b/.test(line)) {
      depth--;
      while (active.length && active[active.length - 1] >= depth) active.pop();
    }
  }
  const server = read('wled00/wled_server.cpp');
  assert.match(server, /server\.on\(castleTekWLEDRoute\(F\("\/settings"\)\), HTTP_GET,[\s\S]*?serveSettings\(request\);/);
  assert.match(server, /server\.on\(castleTekWLEDRoute\(F\("\/settings"\)\), HTTP_POST,[\s\S]*?serveSettings\(request, true\);/);
});
